(() => {
  'use strict';
  const app = document.querySelector('#app');
  const overlayRoot = document.querySelector('#overlay-root');
  const state = {view:'home',period:'شهري',lifecycle:'unknown',chartAlt:false,tool:'cost',cost:42,salary:980,margin:18};
  const periods=['يومي','أسبوعي','شهري','مخصص'];
  const esc=(v)=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
  const money=(v)=>`${Number(v).toLocaleString('en-US')} د.أ`;
  function marker(type='neutral',symbol='•'){return `<span class="marker marker-${type}" aria-hidden="true">${symbol}</span>`}
  function section(title,body,aside=''){return `<section class="section"><div class="section-title"><h3>${title}</h3><span>${aside}</span></div>${body}</section>`}
  function periodControl(){return `<div class="period-strip" role="group" aria-label="الفترة"><span class="sr-only">اختر الفترة</span>${periods.map(p=>`<button class="pill ${state.period===p?'active':''} ${p==='مخصص'?'custom':''}" data-period="${p}">${p}</button>`).join('')}</div>`}
  function commonHead(title,sub){return `<div class="screen-head"><p class="eyebrow">مشهد مراجعة · بيانات توضيحية</p><h2>${title}</h2><p>${sub}</p></div>`}
  function home(){return `<div class="screen">${commonHead('نظرة تشغيلية هادئة','القيمة المباشرة أولًا، ثم ما يستحق الانتباه. كل رقم هنا توضيحي لمراجعة التركيب.')}${section('الفترة',periodControl(),'تطبيق محلي فقط')}${section('القيمة الأساسية',`<div class="surface metric"><span class="metric-label">الرصيد التشغيلي التوضيحي</span><div class="metric-row"><strong class="metric-value" dir="ltr">${money(12480)}</strong>${marker('neutral','≈')}</div><span class="metric-context">سياق العرض: ${state.period} · لا يمثل حقيقة مالية</span><p class="metric-note">العلاقة والمعنى والمصدر يملكها Micro؛ هذا النموذج يختبر الهرمية والوضوح فقط.</p></div>`,'Metric / Balance')}${section('متابعة مختصرة',`<div class="surface attention"><div class="attention-row">${marker('pending','…')}<div class="attention-copy"><b>طلب يحتاج مراجعة بصرية</b><span>حالة توضيحية · لا تعني تعثرًا أو استحقاقًا</span></div><button class="link-btn" data-open="order">فتح</button></div><div class="attention-row">${marker('unknown','?')}<div class="attention-copy"><b>نتيجة غير معروفة</b><span>الخطوة التالية: فحص محلي فقط</span></div><button class="link-btn" data-view="detail">تفاصيل</button></div></div>`,'2 عناصر')}${section('إجراءات سريعة',`<div class="quick-grid"><button class="quick" data-view="orders"><b><span class="clay-mark">＋</span> الطلبات</b><span>عرض تشغيلي محلي</span></button><button class="quick" data-view="finance"><b><span class="ink-mark">◈</span> المالية</b><span>علاقات وقيم توضيحية</span></button><button class="quick" data-view="tools"><b><span class="neutral-mark">⌁</span> الأدوات</b><span>تحليل لا يكتب سجلًا</span></button><button class="quick" data-open="boundary"><b><span class="neutral-mark">i</span> الحدود</b><span>ما الذي لا يفعله النموذج؟</span></button></div>`,'Local')}${section('تمييز الأدوار',`<div class="surface detail-grid"><div class="detail-item"><span>هوية / إنشاء</span><b class="clay-mark">Clay</b></div><div class="detail-item"><span>التزام / قيمة</span><b>Warm-Ink</b></div><div class="detail-item"><span>حالة</span><b>كلمة + marker</b></div><div class="detail-item"><span>هيكل</span><b>Surface / Row</b></div></div>`,'Standard roles')}</div>`}
  function finance(){return `<div class="screen">${commonHead('المالية','تركيب مالي توضيحي يختبر العلاقة بين القيمة والسياق والرسم، لا يثبت سياسة أو مصدرًا.')}${section('الفترة',periodControl(),'Period / DateRange')}${section('Metric / Balance',`<div class="surface metric"><span class="metric-label">قيمة تحليلية توضيحية</span><strong class="metric-value" dir="ltr">${money(18420)}</strong><span class="metric-context">${state.period} · مثال مراجعة فقط</span><div class="metric-note">لا يُستنتج من القيمة أنها رصيد مستحق أو KPI أو حقيقة دفترية.</div></div>`)}${section('Parts / Whole',`<div class="surface"><div class="metric-row"><div><span class="metric-label">المعروض من العلاقة</span><p class="metric-context">أجزاء / مجموع توضيحي</p></div><strong class="op-amount" dir="ltr">7,200 / 12,000</strong></div><div style="margin-top:14px" class="chart-plot" aria-hidden="true"><span class="bar" style="height:60%"></span><span class="bar alt" style="height:38%"></span></div><p class="metric-note" role="note">البديل النصي: الأجزاء المعروضة تساوي 60% من المجموع المرئي. لا يعني الباقي دينًا أو تحصيلًا.</p></div>`)}${section('Question-led SimpleChart',`<div class="surface chart"><strong class="chart-question">كيف تغيّرت القيمة التوضيحية عبر أربع فترات؟</strong><div class="chart-plot" role="img" aria-label="رسم توضيحي لأربع نقاط، ترتفع النقطة الأخيرة مقارنة بالأولى"><span class="bar" style="height:34%"></span><span class="bar" style="height:48%"></span><span class="bar" style="height:42%"></span><span class="bar" style="height:70%"></span></div><div class="chart-axis"><span>W1</span><span>W2</span><span>W3</span><span>W4</span></div><div class="btn-row"><button class="btn btn-secondary" data-chart-alt>${state.chartAlt?'إخفاء البديل النصي':'إظهار البديل النصي'}</button><span class="metric-context">السلسلة الأساسية · zero حاضر</span></div>${state.chartAlt?'<p class="chart-alt">البديل النصي: أربع نقاط توضيحية؛ النقطة الرابعة أعلى من الأولى. الرسم لا يحدد المعادلة أو المصدر أو سبب التغير.</p>':''}</div>`)}${section('حالات للفحص',`<div class="state-list"><div class="state-row">${marker('neutral','○')}<div><b>لا توجد بيانات</b><p>لا توجد قيمة توضيحية لهذه الحالة.</p></div></div><div class="state-row">${marker('pending','…')}<div><b>قيد الانتظار</b><p>لا يعني نجاحًا ولا كتابة سجل.</p></div></div><div class="state-row">${marker('error','!')}<div><b>خطأ · يمكن إعادة الفحص</b><p>الخطأ لا يثبت قابلية الإعادة في المنتج.</p></div></div></div>`,'Explicit states')}</div>`}
  const orders=[['توريد مستلزمات مكتبية — عنوان طويل لاختبار التفاف العربية','13 سبتمبر 2026 · مثال تشغيلي','قيد المراجعة','3,450 د.أ','pending'],['طلب خدمة محلية','12 سبتمبر 2026 · سياق توضيحي','مكتمل العرض','1,280 د.أ','success'],['حركة غير معروفة المصدر','10 سبتمبر 2026 · بيانات ناقصة','غير معروف','—','unknown']];
  function orderRow(o){return `<div class="op-row"><div class="op-copy"><b>${o[0]}</b><span>${o[1]}</span></div><span class="status-word status-${o[4]}">${o[2]}</span><strong class="op-amount" dir="ltr">${o[3]}</strong></div>`}
  function ordersView(){return `<div class="screen">${commonHead('الطلبات','صفوف تشغيلية توضيحية تختبر الالتفاف، الحالة، المبلغ، والسياق دون ربطها بالتسليم.')}${section('قائمة تشغيلية',`<div class="surface operational-list">${orders.map(orderRow).join('')}</div>`,'OperationalRow')}${section('الإجراءات المرئية',`<div class="surface"><p class="metric-context" style="margin-bottom:12px">الصف يعرض، ولا يثبت الصلاحية أو الكتابة.</p><div class="btn-row"><button class="btn btn-primary" data-open="order">فتح تفاصيل</button><button class="btn btn-secondary" data-open="order-sheet">عرض Sheet</button></div></div>`)}${section('حدود المشهد',`<div class="surface record-boundary"><b>التسليم غير منفذ</b><p>وجود الطلب هنا لا يعني أن التسليم اكتمل. هذا placeholder بصري منفصل وغير تشغيلي.</p></div>`,'Out of scope')}</div>`}
  function detail(){const labels={unknown:['نتيجة غير معروفة','?','لم تُثبت النتيجة بعد. الإجراء التالي: إعادة الفحص فقط.','unknown'],pending:['قيد الانتظار','…','الطلب قيد الفحص. لا يعني ذلك نجاحًا أو كتابة سجل.','pending'],retry:['يمكن إعادة الفحص','↻','الفحص السابق لم يثبت نتيجة. إعادة الفحص اختيار مرئي فقط.','retry'],result:['نتيجة مؤكدة توضيحيًا','✓','هذه حالة عرض محلية فقط؛ لا تنشئ سجلًا.','result'],reversed:['أثر معكوس — audit effect','↶','العكس لا يعني محو الأثر السابق. السياسة غير منفذة هنا.','reversed']};const l=labels[state.lifecycle];return `<div class="screen">${commonHead('مراجعة حركة','تفاصيل محلية تشرح ما يمكن عرضه دون تنفيذ تصحيح أو كتابة أو reversal policy.')}${section('القيمة والسياق',`<div class="surface metric"><span class="metric-label">قيمة الحركة التوضيحية</span><strong class="metric-value" dir="ltr">${money(2760)}</strong><span class="metric-context">13 سبتمبر 2026 · طرف توضيحي: جهة تجريبية</span></div>`)}${section('Lifecycle',`<div class="surface state-row">${marker(l[3]==='result'?'success':l[3]==='pending'?'pending':l[3]==='unknown'?'unknown':l[3]==='retry'?'info':'neutral',l[1])}<div style="flex:1"><b>${l[0]}</b><p>${l[2]}</p></div></div><div style="margin-top:12px" class="btn-row"><button class="btn btn-secondary" data-cycle>تبديل الحالة</button><button class="btn btn-primary" data-open="confirm">حدود الإجراء التالي</button></div>`,'State language')}${section('بيانات العلاقة',`<div class="surface detail-grid"><div class="detail-item"><span>الطرف</span><b>طرف توضيحي</b></div><div class="detail-item"><span>نوع العرض</span><b>مراجعة محلية</b></div><div class="detail-item"><span>المصدر</span><b>غير منفذ</b></div><div class="detail-item"><span>صلاحية الكتابة</span><b>خارج النطاق</b></div></div>`)}${section('فصل السجل',`<div class="record-boundary"><b>لا توجد عملية تأكيد أو كتابة</b><p>الزر التالي يفتح شرحًا بصريًا للحدود فقط. لا يتم إنشاء أو تعديل أو عكس أي سجل مالي.</p></div>`)}</div>`}
  function tools(){const total=state.tool==='cost'?state.cost*1.35:state.tool==='salary'?state.salary*1.18:state.margin*100;return `<div class="screen">${commonHead('الأدوات','مساحة تحليل مستقلة. النتيجة illustrative ولا تتحول إلى قيد أو سجل.')}${section('اختر أداة',`<div class="seg">${[['cost','تكلفة منتج'],['salary','تقدير راتب'],['margin','هامش توضيحي']].map(x=>`<button data-tool="${x[0]}" class="${state.tool===x[0]?'active':''}">${x[1]}</button>`).join('')}</div>`)}${section('المدخلات والافتراضات',`<div class="surface tool-form"><div class="field"><label for="tool-input">${state.tool==='cost'?'تكلفة الوحدة التوضيحية':state.tool==='salary'?'الراتب الأساسي التوضيحي':'نسبة الهامش التوضيحية'}</label><input id="tool-input" class="input" type="number" min="0" step="1" value="${state.tool==='cost'?state.cost:state.tool==='salary'?state.salary:state.margin}" data-tool-input></div><p class="metric-context">افتراض محلي ثابت: ${state.tool==='cost'?'إضافة 35% توضيحية':state.tool==='salary'?'إضافة 18% توضيحية':'ضرب النسبة في 100'}.</p><div class="calc-result"><span>النتيجة التحليلية<br>بعد إعادة الحساب</span><strong dir="ltr">${money(total)}</strong></div><button class="btn btn-primary" data-calc>إعادة الحساب</button></div>`)}${section('الفصل عن السجل',`<div class="record-boundary"><b>نتيجة تحليلية فقط</b><p>لا يوجد Save أو Post أو Write. أي تحويل إلى سجل مالي يحتاج قرارًا وتنفيذًا من Micro خارج هذا النموذج.</p><button class="btn btn-ghost" data-open="boundary">عرض الحدود</button></div>`,'ToolResult boundary')}</div>`}
  function render(){app.innerHTML=state.view==='home'?home():state.view==='finance'?finance():state.view==='orders'?ordersView():state.view==='detail'?detail():tools();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));bind();}
  function openSheet(title,content){overlayRoot.innerHTML=`<div class="overlay" data-close-overlay><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-handle"></div><div class="sheet-head"><h2 id="sheet-title">${title}</h2><button class="close-btn" data-close>×</button></div>${content}</section></div>`;overlayRoot.querySelector('.sheet').addEventListener('click',e=>e.stopPropagation());overlayRoot.querySelector('[data-close]').focus();}
  function toast(text){const old=document.querySelector('.toast');if(old)old.remove();const t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=text;document.body.appendChild(t);setTimeout(()=>t.remove(),2600)}
  function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render();app.focus()});document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{state.period=b.dataset.period;if(state.period==='مخصص')openSheet('فترة مخصصة','<div class="tool-form"><div class="field"><label>من</label><input class="input" type="date" value="2026-09-01"></div><div class="field"><label>إلى</label><input class="input" type="date" value="2026-09-13"></div><button class="btn btn-primary" data-close>تطبيق بصري فقط</button><p class="metric-context">لا يطبق هذا النموذج timezone أو owner-day أو completeness policy.</p></div>');render()});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const type=b.dataset.open;if(type==='order'||type==='order-sheet')openSheet('تفاصيل الطلب',`<div class="surface metric"><span class="metric-label">توريد مستلزمات مكتبية</span><strong class="metric-value" dir="ltr">3,450 د.أ</strong><span class="metric-context">قيد المراجعة · 13 سبتمبر 2026</span></div><p class="metric-note">التفاصيل البصرية لا تعني التسليم أو الاستحقاق أو الكتابة.</p><div class="btn-row" style="margin-top:14px"><button class="btn btn-secondary" data-close>إغلاق</button></div>`);if(type==='boundary')openSheet('حدود النموذج','<div class="record-boundary"><b>Review-only prototype</b><p>لا backend، لا auth، لا remote API، لا database، لا sync، ولا financial engine. كل البيانات deterministic ومحلية.</p></div>');if(type==='confirm')openSheet('الحدود قبل الإجراء','<div class="record-boundary"><b>Next-action boundary</b><p>يمكن عرض تأكيد بصري، لكن لا يتم تنفيذ record writing أو reversal policy أو financial correction.</p></div>');if(type==='toggle-info')openSheet('عن النموذج','<div class="record-boundary"><b>Micro Standard v2 · review only</b><p>هذا prototype يختبر تركيب Standard في مشاهد Micro-like. لا ينقل أي كود إلى Micro ولا يغير الحزمة.</p></div>')});document.querySelectorAll('[data-chart-alt]').forEach(b=>b.onclick=()=>{state.chartAlt=!state.chartAlt;render()});document.querySelectorAll('[data-cycle]').forEach(b=>b.onclick=()=>{state.lifecycle={unknown:'pending',pending:'retry',retry:'result',result:'reversed',reversed:'unknown'}[state.lifecycle];render()});document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{state.tool=b.dataset.tool;render()});const input=document.querySelector('[data-tool-input]');if(input)input.oninput=()=>{const n=Math.max(0,Number(input.value)||0);if(state.tool==='cost')state.cost=n;if(state.tool==='salary')state.salary=n;if(state.tool==='margin')state.margin=n};document.querySelectorAll('[data-calc]').forEach(b=>b.onclick=()=>toast('تمت إعادة الحساب محليًا · النتيجة تحليلية فقط'));document.querySelectorAll('[data-close-overlay]').forEach(x=>x.onclick=()=>overlayRoot.innerHTML='');document.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>overlayRoot.innerHTML='')}
  document.querySelector('[data-action="toggle-info"]').onclick=()=>openSheet('عن النموذج','<div class="record-boundary"><b>Review-only prototype</b><p>بيانات محلية deterministic. لا كتابة سجلات ولا اتصال خارجي.</p></div>');
  document.addEventListener('keydown',e=>{if(e.key==='Escape')overlayRoot.innerHTML=''});render();
})();
